#generated by AI

import os
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

sns.set_theme(style="whitegrid")
plt.rcParams.update({
    'font.size': 12,
    'font.family': 'sans-serif',
    'axes.labelsize': 14,
    'axes.titlesize': 16,
    'xtick.labelsize': 11,
    'ytick.labelsize': 11,
    'figure.titlesize': 18,
    'pdf.fonttype': 42,
    'ps.fonttype': 42
})

OUTPUT_DIR = "output_plots"
os.makedirs(OUTPUT_DIR, exist_ok=True)

gpu_csv_path = 'nids_comparison_ruleset_scaling_gpu.csv'
cpu_csv_path = 'nids_comparison_ruleset_scaling_cpu.csv'

if not os.path.exists(gpu_csv_path) and os.path.exists(f'../{gpu_csv_path}'):
    gpu_csv_path = f'../{gpu_csv_path}'
if not os.path.exists(cpu_csv_path) and os.path.exists(f'../{cpu_csv_path}'):
    cpu_csv_path = f'../{cpu_csv_path}'

df_gpu = pd.read_csv(gpu_csv_path)
df_cpu = pd.read_csv(cpu_csv_path)

gpu_stats = df_gpu.groupby('Nbr_Pattern').agg({
    'Througput': ['mean', 'std'],
    'Memory_MB': ['mean'],
    'NB_Matches': ['mean']
}).reset_index()
gpu_stats.columns = ['patterns', 'throughput_mean', 'throughput_std', 'memory_mean', 'matches_mean']
gpu_stats = gpu_stats.fillna(0)

cpu_stats = df_cpu.groupby('Nbr_Pattern').agg({
    'Througput': ['mean', 'std'],
    'Memory_MB': ['mean'],
    'NB_Matches': ['mean']
}).reset_index()
cpu_stats.columns = ['patterns', 'throughput_mean', 'throughput_std', 'memory_mean', 'matches_mean']
cpu_stats = cpu_stats.fillna(0)

x_labels = [str(p) for p in gpu_stats['patterns']]
x_indexes = list(range(len(x_labels)))

plt.figure(figsize=(10, 6))
plt.plot(x_indexes, gpu_stats['memory_mean'], marker='o', color='#1f77b4', linewidth=2.5, markersize=8, label='DFA Memory (MB)')
for i, txt in enumerate(gpu_stats['memory_mean']):
    plt.annotate(f'{txt:.1f}', (x_indexes[i], gpu_stats['memory_mean'][i]), 
                 textcoords="offset points", xytext=(0, 10), ha='center', fontsize=9, fontweight='bold')
plt.xticks(x_indexes, x_labels)
plt.title('GPU DFA Memory Scaling with Rule Count', pad=15)
plt.xlabel('Number of Rules (Patterns)')
plt.ylabel('Memory Size (MB)')
plt.legend(loc='upper left')
plt.tight_layout()
plt.savefig(os.path.join(OUTPUT_DIR, 'chart_gpu_memory_scaling.pdf'), format='pdf', bbox_inches='tight')
plt.close()

plt.figure(figsize=(10, 6))
plt.plot(x_indexes, gpu_stats['throughput_mean'], marker='o', color='#2ca02c', linewidth=2.5, markersize=8, label='Throughput (Gbps)')
plt.fill_between(x_indexes, 
                 gpu_stats['throughput_mean'] - gpu_stats['throughput_std'], 
                 gpu_stats['throughput_mean'] + gpu_stats['throughput_std'], 
                 color='#2ca02c', alpha=0.2)
for i, txt in enumerate(gpu_stats['throughput_mean']):
    plt.annotate(f'{txt:.2f}', (x_indexes[i], gpu_stats['throughput_mean'][i]), 
                 textcoords="offset points", xytext=(0, 10), ha='center', fontsize=9, fontweight='bold')
plt.xticks(x_indexes, x_labels)
plt.title('GPU Throughput Stability Across Rule Counts', pad=15)
plt.xlabel('Number of Rules (Patterns)')
plt.ylabel('Throughput (Gbps)')
plt.ylim(15, 23)
plt.legend(loc='lower left')
plt.tight_layout()
plt.savefig(os.path.join(OUTPUT_DIR, 'chart_gpu_throughput_scaling.pdf'), format='pdf', bbox_inches='tight')
plt.close()

plt.figure(figsize=(10, 6))
plt.plot(x_indexes, cpu_stats['memory_mean'], marker='s', color='#ff7f0e', linewidth=2.5, markersize=8, label='DFA Memory (MB)')
for i, txt in enumerate(cpu_stats['memory_mean']):
    plt.annotate(f'{txt:.1f}', (x_indexes[i], cpu_stats['memory_mean'][i]), 
                 textcoords="offset points", xytext=(0, 10), ha='center', fontsize=9, fontweight='bold')
plt.xticks(x_indexes, x_labels)
plt.title('CPU DFA Memory Scaling with Rule Count', pad=15)
plt.xlabel('Number of Rules (Patterns)')
plt.ylabel('Memory Size (MB)')
plt.legend(loc='upper left')
plt.tight_layout()
plt.savefig(os.path.join(OUTPUT_DIR, 'chart_cpu_memory_scaling.pdf'), format='pdf', bbox_inches='tight')
plt.close()

plt.figure(figsize=(10, 6))
plt.plot(x_indexes, cpu_stats['throughput_mean'], marker='s', color='#d62728', linewidth=2.5, markersize=8, label='Throughput (Gbps)')
plt.fill_between(x_indexes, 
                 cpu_stats['throughput_mean'] - cpu_stats['throughput_std'], 
                 cpu_stats['throughput_mean'] + cpu_stats['throughput_std'], 
                 color='#d62728', alpha=0.2)
for i, txt in enumerate(cpu_stats['throughput_mean']):
    plt.annotate(f'{txt:.2f}', (x_indexes[i], cpu_stats['throughput_mean'][i]), 
                 textcoords="offset points", xytext=(0, 10), ha='center', fontsize=9, fontweight='bold')
plt.xticks(x_indexes, x_labels)
plt.title('CPU Throughput Stability Across Rule Counts', pad=15)
plt.xlabel('Number of Rules (Patterns)')
plt.ylabel('Throughput (Gbps)')
plt.ylim(8, 16)
plt.legend(loc='lower left')
plt.tight_layout()
plt.savefig(os.path.join(OUTPUT_DIR, 'chart_cpu_throughput_scaling.pdf'), format='pdf', bbox_inches='tight')
plt.close()

plt.figure(figsize=(10, 6))
plt.plot(x_indexes, cpu_stats['matches_mean'], marker='s', color='#d62728', linewidth=2, markersize=7, label='CPU Matches')
plt.plot(x_indexes, gpu_stats['matches_mean'], marker='o', color='#2ca02c', linewidth=2, linestyle='--', markersize=7, label='GPU Matches')

for i, txt in enumerate(cpu_stats['matches_mean']):
    val = int(txt)
    plt.annotate(f'{val:,}', (x_indexes[i], cpu_stats['matches_mean'][i]), 
                 textcoords="offset points", xytext=(0, 12), ha='center', fontsize=8, color='#d62728', fontweight='bold')

for i, txt in enumerate(gpu_stats['matches_mean']):
    val = int(txt)
    plt.annotate(f'{val:,}', (x_indexes[i], gpu_stats['matches_mean'][i]), 
                 textcoords="offset points", xytext=(0, -15), ha='center', fontsize=8, color='#2ca02c', fontweight='bold')

plt.gca().ticklabel_format(style='plain', axis='y')
plt.gca().get_yaxis().set_major_formatter(plt.FuncFormatter(lambda x, loc: "{:,}".format(int(x))))

plt.xticks(x_indexes, x_labels, rotation=30)
plt.title('Detection Accuracy: Total Matches Comparison (CPU vs GPU)', pad=15)
plt.xlabel('Number of Rules (Patterns)')
plt.ylabel('Total Matches Detected')
plt.legend(loc='upper left')
plt.tight_layout()
plt.savefig(os.path.join(OUTPUT_DIR, 'chart_matches_comparison.pdf'), format='pdf', bbox_inches='tight')
plt.close()